  ["UI_SC_Base_ProductionFireWarning"] = "\\u0627\\u0644\\u062D\\u0631\\u0642 \\u064A\\u0634\\u0639\\u0644 \\u0646\\u0627\\u0631\\u064B\\u0627 \\u062D\\u0642\\u064A\\u0642\\u064A\\u0629 \\u0642\\u062F \\u062A\\u0646\\u062A\\u0634\\u0631 \\u0625\\u0646 \\u0643\\u0627\\u0646 \\u062E\\u064A\\u0627\\u0631 \\u0627\\u0646\\u062A\\u0634\\u0627\\u0631 \\u0627\\u0644\\u0646\\u0627\\u0631 \\u0645\\u0641\\u0639\\u0651\\u0644\\u064B\\u0627. \\u0623\\u0628\\u0639\\u062F \\u0627\\u0644\\u0645\\u062D\\u0631\\u0642\\u0629 \\u0639\\u0646 \\u0643\\u0644 \\u0645\\u0627 \\u062A\\u0631\\u064A\\u062F \\u0627\\u0644\\u062D\\u0641\\u0627\\u0638 \\u0639\\u0644\\u064A\\u0647.",
