  ["UI_SC_Base_ProductionHint_burn_bodies"] = "\\u064A\\u062D\\u0631\\u0642 \\u0627\\u0644\\u062C\\u062B\\u062B \\u0627\\u0644\\u0645\\u0648\\u0636\\u0648\\u0639\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u062D\\u0631\\u0642\\u0629 \\u0627\\u0644\\u0645\\u062E\\u062A\\u0627\\u0631\\u0629 \\u0628\\u0623\\u064A \\u0623\\u062F\\u0627\\u0629 \\u0625\\u0634\\u0639\\u0627\\u0644 \\u0635\\u0627\\u0644\\u062D\\u0629 \\u0648\\u0639\\u0644\\u0628\\u0629 \\u0628\\u0646\\u0632\\u064A\\u0646 \\u0645\\u0646 \\u0645\\u062E\\u0632\\u0646 \\u0627\\u0644\\u0645\\u062E\\u064A\\u0645. \\u0627\\u0644\\u062D\\u0631\\u0642 \\u0646\\u0627\\u0631 \\u062D\\u0642\\u064A\\u0642\\u064A\\u0629: \\u064A\\u062C\\u0628 \\u0623\\u0646 \\u062A\\u0643\\u0648\\u0646 \\u0627\\u0644\\u0645\\u062D\\u0631\\u0642\\u0629 \\u0641\\u064A \\u0627\\u0644\\u062E\\u0627\\u0631\\u062C \\u0648\\u0628\\u0639\\u064A\\u062F\\u0629 \\u0639\\u0646 \\u0627\\u0644\\u0645\\u0628\\u0627\\u0646\\u064A \\u0648\\u0627\\u0644\\u0623\\u0634\\u062C\\u0627\\u0631 \\u0648\\u0627\\u0644\\u0623\\u063A\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0645\\u062E\\u0632\\u0646\\u0629. \\u0644\\u0627 \\u064A\\u064F\\u0634\\u0639\\u0644 \\u0634\\u064A\\u0621 \\u0641\\u064A \\u0627\\u0644\\u0645\\u0637\\u0631\\u060C \\u0648\\u064A\\u062A\\u0648\\u0642\\u0641 \\u0643\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0627\\u0644 \\u0625\\u0646 \\u0627\\u0646\\u062A\\u0634\\u0631\\u062A \\u0627\\u0644\\u0646\\u0627\\u0631.",
  ["UI_SC_Base_ProductionHint_bury_bodies"] = "\\u064A\\u062F\\u0641\\u0646 \\u0627\\u0644\\u062C\\u062B\\u062B \\u0627\\u0644\\u0645\\u0644\\u0642\\u0627\\u0629 \\u0639\\u0644\\u0649 \\u0628\\u0639\\u062F \\u062E\\u0627\\u0646\\u062A\\u064A\\u0646 \\u0645\\u0646 \\u0642\\u0628\\u0631 \\u0645\\u0641\\u062A\\u0648\\u062D \\u0641\\u064A \\u0627\\u0644\\u0645\\u0642\\u0628\\u0631\\u0629\\u060C \\u0648\\u064A\\u062D\\u0641\\u0631 \\u0642\\u0628\\u0631\\u064B\\u0627 \\u0625\\u0646 \\u0644\\u0645 \\u064A\\u0648\\u062C\\u062F\\u060C \\u062B\\u0645 \\u064A\\u0631\\u062F\\u0645 \\u0627\\u0644\\u0642\\u0628\\u0631 \\u0648\\u064A\\u0642\\u0648\\u0644 \\u0643\\u0644\\u0645\\u0627\\u062A \\u0642\\u0644\\u064A\\u0644\\u0629.",
  ["UI_SC_Base_ProductionHint_collect_bodies"] = "\\u0627\\u062E\\u062A\\u0631 \\u0627\\u0644\\u062F\\u0641\\u0646 \\u0623\\u0648 \\u0627\\u0644\\u0645\\u062D\\u0631\\u0642\\u0629\\u060C \\u062B\\u0645 \\u0627\\u0644\\u0645\\u0646\\u0637\\u0642\\u0629 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628\\u0629. \\u064A\\u062C\\u062F \\u0627\\u0644\\u0639\\u0627\\u0645\\u0644 \\u0627\\u0644\\u062C\\u062B\\u062B \\u062F\\u0627\\u062E\\u0644 \\u0627\\u0644\\u0645\\u062E\\u064A\\u0645 \\u0648\\u0645\\u0646\\u0627\\u0637\\u0642 \\u0627\\u0644\\u062D\\u0637\\u0628\\u060C \\u0648\\u064A\\u0633\\u062D\\u0628\\u0647\\u0627 \\u0625\\u0644\\u0649 \\u0647\\u0646\\u0627\\u0643\\u060C \\u0641\\u064A\\u062F\\u0641\\u0646\\u0647\\u0627 \\u0623\\u0648 \\u064A\\u062D\\u0631\\u0642\\u0647\\u0627. \\u0627\\u0644\\u0631\\u0641\\u0642\\u0627\\u0621 \\u0627\\u0644\\u0631\\u0627\\u062D\\u0644\\u0648\\u0646 \\u064A\\u064F\\u062F\\u0641\\u0646\\u0648\\u0646 \\u062F\\u0627\\u0626\\u0645\\u064B\\u0627 \\u0641\\u064A \\u0642\\u0628\\u0631 \\u0628\\u0627\\u0633\\u0645\\u0647\\u0645\\u060C \\u0648\\u0644\\u0627 \\u064A\\u064F\\u062D\\u0631\\u0642\\u0648\\u0646 \\u0623\\u0628\\u062F\\u064B\\u0627. \\u0648\\u064A\\u062A\\u0631\\u0643 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0644 \\u0627\\u0644\\u062C\\u062B\\u0629 \\u0641\\u0648\\u0631\\u064B\\u0627 \\u0639\\u0646\\u062F \\u0638\\u0647\\u0648\\u0631 \\u0627\\u0644\\u062E\\u0637\\u0631.",
  ["UI_SC_Base_ProductionHint_dig_graves"] = "\\u064A\\u062D\\u0641\\u0631 \\u0627\\u0644\\u0642\\u0628\\u0648\\u0631 \\u0641\\u064A \\u0627\\u0644\\u0623\\u0631\\u0636 \\u0627\\u0644\\u0637\\u0628\\u064A\\u0639\\u064A\\u0629 \\u062F\\u0627\\u062E\\u0644 \\u0627\\u0644\\u0645\\u0642\\u0628\\u0631\\u0629 \\u0628\\u0627\\u0644\\u0645\\u062C\\u0631\\u0641\\u0629.",
