  ["UI_SC_Doctrine_CloseDefense"] = "\\u0627\\u0644\\u062F\\u0641\\u0627\\u0639 \\u0627\\u0644\\u0642\\u0631\\u064A\\u0628",
  ["UI_SC_Doctrine_CloseDefense_Tooltip"] = "\\u0625\\u0632\\u0627\\u0644\\u0629 \\u0627\\u0644\\u062A\\u0647\\u062F\\u064A\\u062F\\u0627\\u062A \\u0627\\u0644\\u0642\\u0631\\u064A\\u0628\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0641\\u0631\\u064A\\u0642 \\u062F\\u0648\\u0646 \\u0645\\u0637\\u0627\\u0631\\u062F\\u0629 \\u0627\\u0644\\u0632\\u0648\\u0645\\u0628\\u064A \\u0627\\u0644\\u0628\\u0639\\u064A\\u062F\\u064A\\u0646. \\u0627\\u0633\\u062A\\u062E\\u062F\\u0627\\u0645 \\u0623\\u0641\\u0636\\u0644 \\u0633\\u0644\\u0627\\u062D \\u0645\\u062A\\u0627\\u062D. \\u0644\\u0627 \\u0625\\u0637\\u0644\\u0627\\u0642 \\u0646\\u0627\\u0631 \\u0645\\u0646 \\u0645\\u0631\\u0643\\u0628\\u0629.",
  ["UI_SC_Doctrine_RangedSupport"] = "\\u0627\\u0644\\u062F\\u0639\\u0645 \\u0627\\u0644\\u0628\\u0639\\u064A\\u062F",
